<?php
/** Template Name: خدمات تخصصی */
declare(strict_types=1);
if (!defined('ABSPATH')) exit;
get_header();
$postId = (int) get_the_ID();
$services = get_pages(['post_type' => 'page', 'post_status' => 'publish', 'parent' => $postId, 'sort_column' => 'menu_order,post_title', 'sort_order' => 'ASC']);
if (!is_array($services)) $services = [];
?>
